// Extract Jordan's initial thoughts
const response = $input.first().json;
const jordanThoughts = response.output || response.text || '';

console.log('=== JORDAN INITIAL THOUGHTS ===');
console.log('Response length:', jordanThoughts.length);

// Get manuscript ID from webhook
const manuscriptId = $('Webhook').first().json.body.manuscriptId;

return {
  json: {
    manuscriptId: manuscriptId,
    jordanThoughts: jordanThoughts.trim(),
    timestamp: new Date().toISOString()
  }
};

const jordanThoughts =
  $json.jordanThoughts ||
  "Jordan is analyzing the manuscript for technical excellence!";
const manuscriptData = $("Fetch Manuscript").first().json;

// Convert markdown to HTML
const htmlAnalysis = jordanThoughts
  .replace(/\*\*(.*?)\*\*/g, '<strong style="font-weight: 600;">$1</strong>')
  .replace(/\*(.*?)\*/g, "<em>$1</em>")
  .replace(/\n\n/g, '</p><p style="margin: 15px 0; line-height: 1.6;">')
  .replace(/^/, '<p style="margin: 15px 0; line-height: 1.6;">')
  .replace(/$/, "</p>");

const currentDate = new Date().toLocaleDateString("en-US", {
  year: "numeric",
  month: "long",
  day: "numeric",
});

const reportData = {
  authorName:
    `${manuscriptData.author_first_name || ""} ${manuscriptData.author_last_name || ""}`.trim() ||
    "Author",
  manuscriptTitle: manuscriptData.title || "Untitled",
  analysisDate: currentDate,
  totalWordCount: (manuscriptData.current_word_count || 0).toLocaleString(),
  genre: manuscriptData.genre || "Fiction",
  analysisReport: htmlAnalysis,
  manuscriptId: $json.manuscriptId,
};

console.log("✅ Jordan report formatted for PDF");
return { json: reportData };

const response = $json;

if (response.status !== 'success') {
  throw new Error('PDF generation failed');
}

const pdfUrl = response.download_url || response.download_url_pdf;
const manuscriptId = $('Parse Response').first().json.manuscriptId;

console.log('✅ PDF URL:', pdfUrl);

// Pass through the binary data from "Create a pdf" node
return {
  json: {
    pdfUrl: pdfUrl,
    manuscriptId: manuscriptId
  },
  binary: $binary  // <-- This passes through the binary data
};

const key = $json.Key;
const match = key.match(/manuscript-reports\/([a-f0-9-]+)_report\.pdf/);  // Changed: removed "sam_"
const manuscriptId = match ? match[1] : null;

if (!manuscriptId) {
  throw new Error(`Could not extract manuscript ID from: ${key}`);
}

const publicUrl = `https://itlkncjiifbgvmvuejgm.supabase.co/storage/v1/object/public/${key}`;

console.log('✅ Sam PDF uploaded:', publicUrl);

return {
  json: {
    manuscriptId: manuscriptId,
    reportUrl: publicUrl
  }
};

const author = $json;
const reportUrl = $('Extract ManuscriptID').first().json.reportUrl;

return {
  json: {
    to: author.email,
    subject: `🔍 Jordan's Copy Editing Report for "${author.manuscript_title}"`,
    body: `Hi ${author.first_name},

I've completed my technical review of your manuscript and I'm impressed with the quality Sam helped you achieve!

📄 View your complete copy-editing report:
${reportUrl}

The prose work is solid—now let's ensure every detail is technically perfect. 🔍

Ready to polish? Head back to your Author Studio and click on any chapter to see my specific notes.

—Jordan
Your Copy Editor`,
    reportUrl: reportUrl
  }
};

const cellReturn = $input.first().json;
return [{ json: {
  output: cellReturn.ok ? (cellReturn.content || '') : '',
  ok: !!cellReturn.ok,
  cell_terminal_reason: cellReturn.ok ? null : (cellReturn.terminal_reason || 'unknown'),
  cell_model: cellReturn.model || null,
  cell_input_tokens: cellReturn.input_tokens || null,
  cell_output_tokens: cellReturn.output_tokens || null,
  cell_latency_ms: cellReturn.latency_ms || null,
  cell_cost_usd: cellReturn.cost_estimate_usd || null
}}];
